import Vonage from '@vonage/server-sdk';

const vonage = new Vonage({
  apiKey: process.env.VONAGE_API_KEY!,
  apiSecret: process.env.VONAGE_API_SECRET!,
});

const response = await vonage.sms.send({
  to: '14155551234',
  from: 'YourBrand', // Alphanumeric sender ID (not available in all countries)
  text: 'Your verification code is 382910. Expires in 10 minutes.',
});

const result = response.messages[0];
if (result?.status === '0') {
  console.log('SMS sent successfully, ID:', result['message-id']);
} else {
  console.error('Failed to send SMS:', result?.['error-text']);
}

import Vonage from '@vonage/server-sdk';

const vonage = new Vonage({
  apiKey: process.env.VONAGE_API_KEY!,
  apiSecret: process.env.VONAGE_API_SECRET!,
});

// Start verification
const verifyResponse = await vonage.verify.start({
  number: '14155551234',
  brand: 'MyApp',
});
const requestId = verifyResponse.request_id;
console.log('Verification started, request ID:', requestId);

// Later — check the code user entered
const checkResponse = await vonage.verify.check(requestId, '1234');
if (checkResponse.status === '0') {
  console.log('Phone number verified successfully!');
}
